-- Apply after the initial schema. Removes anonymous access to child welfare records.
create table if not exists public.user_profiles (user_id uuid primary key references auth.users(id) on delete cascade, display_name text, role text not null default 'case_worker' check(role in ('admin','case_worker','read_only')), preferred_language text not null default 'en' check(preferred_language in ('en','hi','or','bn','ta','te')), created_at timestamptz not null default now());
alter table public.user_profiles enable row level security; revoke all on public.user_profiles from anon; grant select on public.user_profiles to authenticated;
drop policy if exists "profile self read" on public.user_profiles; create policy "profile self read" on public.user_profiles for select to authenticated using(user_id=(select auth.uid()));
create or replace function public.current_staff_role() returns text language sql stable security definer set search_path=public as $$ select role from public.user_profiles where user_id=(select auth.uid()) $$; revoke all on function public.current_staff_role() from public; grant execute on function public.current_staff_role() to authenticated;
do $$ declare t text; begin foreach t in array array['centers','children','health_records','case_notes','handoffs','consents'] loop execute format('revoke all on public.%I from anon',t); execute format('grant select,insert,update,delete on public.%I to authenticated',t); execute format('alter table public.%I enable row level security',t); execute format('drop policy if exists "anon_select_%s" on public.%I',t,t); execute format('drop policy if exists "anon_insert_%s" on public.%I',t,t); execute format('drop policy if exists "anon_update_%s" on public.%I',t,t); execute format('drop policy if exists "anon_delete_%s" on public.%I',t,t); execute format('drop policy if exists "staff read" on public.%I',t); execute format('drop policy if exists "staff insert" on public.%I',t); execute format('drop policy if exists "staff update" on public.%I',t); execute format('drop policy if exists "admin delete" on public.%I',t); execute format('create policy "staff read" on public.%I for select to authenticated using(public.current_staff_role() in (''admin'',''case_worker'',''read_only''))',t); execute format('create policy "staff insert" on public.%I for insert to authenticated with check(public.current_staff_role() in (''admin'',''case_worker''))',t); execute format('create policy "staff update" on public.%I for update to authenticated using(public.current_staff_role() in (''admin'',''case_worker'')) with check(public.current_staff_role() in (''admin'',''case_worker''))',t); execute format('create policy "admin delete" on public.%I for delete to authenticated using(public.current_staff_role()=''admin'')',t); end loop; end $$;
create table if not exists public.family_links(id uuid primary key default gen_random_uuid(),child_id uuid not null references public.children(id) on delete cascade,relationship text not null,full_name text not null,contact_phone text,district text,verified boolean not null default false,notes text,created_by uuid references auth.users(id),created_at timestamptz not null default now());
create table if not exists public.migration_events(id uuid primary key default gen_random_uuid(),child_id uuid references public.children(id) on delete set null,event_date date not null default current_date,from_district text,to_district text,migration_reason text,source_verified boolean not null default false,notes text,created_by uuid references auth.users(id),created_at timestamptz not null default now());
create table if not exists public.schooling_records(id uuid primary key default gen_random_uuid(),child_id uuid not null unique references public.children(id) on delete cascade,school_name text,grade_level text,enrollment_status text not null default 'unknown' check(enrollment_status in ('enrolled','not_enrolled','discontinued','unknown')),attendance_percent numeric check(attendance_percent between 0 and 100),language_of_instruction text,last_verified_at date,notes text,updated_at timestamptz not null default now());
create table if not exists public.childcare_directory(id uuid primary key default gen_random_uuid(),name text not null,service_type text not null check(service_type in ('anganwadi','school','health','shelter','counselling','other')),district text not null,address text,contact_phone text,languages text[] not null default '{}',is_active boolean not null default true,created_at timestamptz not null default now());
create index if not exists idx_family_links_child_id on public.family_links(child_id); create index if not exists idx_migration_events_child_date on public.migration_events(child_id,event_date desc); create index if not exists idx_schooling_records_child_id on public.schooling_records(child_id); create index if not exists idx_childcare_directory_district on public.childcare_directory(district);
do $$ declare t text; begin foreach t in array array['family_links','migration_events','schooling_records','childcare_directory'] loop execute format('alter table public.%I enable row level security',t); execute format('revoke all on public.%I from anon',t); execute format('grant select,insert,update,delete on public.%I to authenticated',t); execute format('create policy "staff read" on public.%I for select to authenticated using(public.current_staff_role() in (''admin'',''case_worker'',''read_only''))',t); execute format('create policy "staff insert" on public.%I for insert to authenticated with check(public.current_staff_role() in (''admin'',''case_worker''))',t); execute format('create policy "staff update" on public.%I for update to authenticated using(public.current_staff_role() in (''admin'',''case_worker'')) with check(public.current_staff_role() in (''admin'',''case_worker''))',t); execute format('create policy "admin delete" on public.%I for delete to authenticated using(public.current_staff_role()=''admin'')',t); end loop; end $$;
